   try:
    while child.poll() is None:
     now=time.monotonic();require(now-start<allowance,'Stage time limit: '+label,'BUDGET')
     if now-last>=10:
      require(memory()['available_bytes']>=256<<20,'System memory pressure','MEMORY')
      require(shutil.disk_usage(self.out).free>=256<<20,'Disk pressure','STORAGE')
      print('HEARTBEAT',label,'elapsed_seconds',round(now-start),'remaining_seconds',round(self.deadline-now),flush=True);last=now
     time.sleep(.1)
   except BaseException:
    try:os.killpg(child.pid,signal.SIGTERM);child.wait(timeout=3)
    except (ProcessLookupError,subprocess.TimeoutExpired):
     try:os.killpg(child.pid,signal.SIGKILL);child.wait(timeout=2)
     except (ProcessLookupError,subprocess.TimeoutExpired):pass
