def readonly(fn):
 for attempt in range(2):
  try:return fn()
  except Exception as e:
   response=get(e,'response');code=get(response,'status_code')
   if code not in (429,500,502,503,504) or attempt==1:raise
   wait=get(get(response,'headers',default={}), 'Retry-After',default='1')
   try:delay=max(1,float(wait))
   except (ValueError,TypeError):raise Stop('REMOTE_SERVICE','Unparseable server backoff')
   require(delay<=3,'Server backoff exceeds audit bound','REMOTE_SERVICE');time.sleep(delay)

def observe(api):
 from kagglesdk.competitions.types.competition_api_service import ApiListSubmissionsRequest
 from kagglesdk.competitions.types.competition_enums import SubmissionGroup,SubmissionSortBy
 rows=[];token='';seen=set()
 for page in range(1,21):
  request=ApiListSubmissionsRequest();request.competition_name=COMPETITION
  request.group=SubmissionGroup.SUBMISSION_GROUP_ALL;request.sort_by=SubmissionSortBy.SUBMISSION_SORT_BY_DATE
  request.page_size=100;request.page_token=token
  def fetch():
   with api.build_kaggle_client() as client:
    return client.competitions.competition_api_client.list_submissions(request)
  response=readonly(fetch);raw=get(response,'submissions')
  require(isinstance(raw,(list,tuple)) and all(x is not None for x in raw),'Incomplete/malformed authenticated submission inventory','SDK_PROTOCOL')
  rows.extend(score_row(r) for r in raw);nxt=get(response,'next_page_token','nextPageToken',default='')
  if not nxt:
   refs=[r['ref'] for r in rows];require(len(refs)==len(set(refs)),'Repeated submission references','SDK_PROTOCOL')
   return {'status':'observed','observed_utc':utc(),'complete':True,'submissions':rows,'pages':page,'kaggle_write_calls':0}
  require(isinstance(nxt,str) and nxt not in seen,'Invalid/repeated submission cursor','SDK_PROTOCOL');seen.add(nxt);token=nxt
