def main(out):
 captured=io.StringIO()
 try:
  with contextlib.redirect_stdout(captured),contextlib.redirect_stderr(captured):
   from kaggle.api.kaggle_api_extended import KaggleApi
   api=KaggleApi();api.authenticate();data=observe(api)
