def seconds_left(): return DEADLINE_TS-time.time()

class Runner:
    def __init__(self,args):
        self.root=args.root.resolve()
        self.out=self.root/OUT_REL
        self.prev=self.root/PREV_REL
        self.run_id=datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        self.run=self.out/"runs"/self.run_id
        self.run.mkdir(parents=True,exist_ok=True)
        self.ret=args.return_path
        self.deadline=time.monotonic()+args.max_seconds
        self.max_cost=args.max_cost_usd
