    def checkpoint(self):
        self.receipt["elapsed_seconds"]=round(time.monotonic()-self.start,3)
        self.receipt["estimated_instance_cost_usd"]=round(self.receipt["elapsed_seconds"]/3600*RATE,6)
        atomic_json(self.run/"run_receipt.json",self.receipt); atomic_json(self.out/"latest_receipt.json",self.receipt)
    def log_event(self,**kw):
        kw={"utc":utc(),"elapsed_seconds":round(time.monotonic()-self.start,3),**kw}
        self.events.append(kw); atomic_json(self.run/"events.json",self.events)
    def command(self,argv,label,timeout,env=None,check=True):
        left=min(timeout,max(1,self.deadline-time.monotonic()))
        logp=self.run/(f"{len(self.events)+1:03d}_{label}.log")
        self.log_event(stage="COMMAND_START",label=label,argv=[str(x) for x in argv])
        with logp.open("w") as fh:
            p=subprocess.Popen([str(x) for x in argv],cwd=self.root,env=env,stdout=fh,stderr=subprocess.STDOUT,start_new_session=True)
            st=time.monotonic()
            while p.poll() is None:
                if time.monotonic()-st>left:
                    try: os.killpg(p.pid,signal.SIGTERM)
                    except ProcessLookupError: pass
                    try:p.wait(8)
                    except subprocess.TimeoutExpired:
                        try:os.killpg(p.pid,signal.SIGKILL)
                        except ProcessLookupError:pass
                        p.wait()
                    self.log_event(stage="COMMAND_TIMEOUT",label=label)
                    raise TimeoutError(label+" timeout")
                try:p.wait(timeout=min(15,max(.2,left-(time.monotonic()-st))))
                except subprocess.TimeoutExpired:
