def nb_code_hash(path: Path) -> dict:
    nb=json.loads(Path(path).read_text())
    cells=[]
    for c in nb.get("cells",[]):
        if c.get("cell_type") != "code": continue
        src=c.get("source","")
        cells.append("".join(src) if isinstance(src,list) else str(src))
    return {
        "count":len(cells),
        "cells_nul":hashlib.sha256("\n\0\n".join(cells).encode()).hexdigest(),
        "cells_double_newline":hashlib.sha256("\n\n".join(cells).encode()).hexdigest(),
    }

def scrub(s: str) -> str:
    s=str(s)
    s=re.sub(r"(?i)(authorization\s*[:=]\s*)([^\r\n]+)",r"\1[REDACTED]",s)
    s=re.sub(r"(?i)((?:token|api[_-]?key|password|x-amz-signature|x-amz-credential)=)[^\s&]+",r"\1[REDACTED]",s)
