def scrub(s):
    s=str(s)
    s=re.sub(r'(?i)(authorization\s*[:=]\s*)([^\r\n]+)',r'\1[REDACTED]',s)
    s=re.sub(r'(?i)((?:token|api[_-]?key|password|x-amz-signature|x-amz-credential)=)[^\s&]+',r'\1[REDACTED]',s)
    return s

def parse_submission_csv(text):
    lines=[x for x in text.splitlines() if x.strip()]
    start=None
    for i,x in enumerate(lines):
        low=x.lower().replace(' ','')
        if low.startswith('ref,') and 'status' in low: start=i; break
    if start is None:return []
    return list(csv.DictReader(io.StringIO('\n'.join(lines[start:]))))

def row_ref(r):
    for k in ('ref','Ref','reference','submissionRef'):
        if r.get(k):return str(r[k]).strip()
    return ''
def row_desc(r):
    for k in ('description','Description','message','Message'):
        if r.get(k):return str(r[k])
    return ''
def row_status(r):
    for k in ('status','Status'):
        if r.get(k):return str(r[k]).upper()
    return ''
def row_score(r):
    for k in ('publicScore','public_score','Public Score','score'):
        v=r.get(k)
        if v not in (None,''):
            try:return float(v)
            except Exception:pass
    return None
def row_date(r):
    for k in ('date','Date','submittedAt','submissionDate'):
        if r.get(k):return str(r[k])
    return ''

def validate_submission_file(path):
    path=Path(path); require(path.is_file(),'submission.csv missing','SOURCE_STATE'); require(path.stat().st_size>1000,'submission.csv implausibly small','SCHEMA')
    with path.open('r',newline='') as f:
        rd=csv.DictReader(f); cols=rd.fieldnames or []
        need={'id','dataset','row_type','node_id','t','z','y','x','source_id','target_id'}
        require(need.issubset(set(cols)),f'missing columns {sorted(need-set(cols))}','SCHEMA')
        n=nodes=edges=0; datasets=set(); ids=[]
        for row in rd:
            n+=1; datasets.add(row.get('dataset','')); typ=row.get('row_type','')
            if typ=='node':nodes+=1
            elif typ=='edge':edges+=1
            else:raise Stop('SCHEMA',f'Unexpected row_type {typ!r}')
            try:ids.append(int(row['id']))
            except Exception:raise Stop('SCHEMA','Non-integer id')
        require(n and nodes and edges and datasets,'submission lacks graph content','SCHEMA')
        require(ids[0]==0 and ids[-1]==n-1 and len(set(ids))==n,'id range is not unique 0..N-1','SCHEMA')
    return {'rows':n,'nodes':nodes,'edges':edges,'datasets':len(datasets),'bytes':path.stat().st_size}

def candidate_tag(label,out_sha):return f'biohub-public0953-diverse-{label}-{out_sha[:12]}'

def allowed_new_slots(daily_count):
    return max(0,min(MAX_NEW_THIS_RUN,MAX_DAILY_SUBMISSIONS-RESERVE_DAILY_SLOTS-daily_count))

