        self.run=self.state/'runs'/self.run_id; self.logs=self.run/'logs'; self.logs.mkdir(parents=True,exist_ok=True)
        self.py=self.root/'.venv/bin/python'; self.kaggle=None; self.events=[]; self.new_submissions=[]; self.audit_records=[]
