        if kw:print(scrub(json.dumps(kw,sort_keys=True)),flush=True)
    def cmd(self,argv,label,timeout=120,ok=(0,)):
        self.budget(); timeout=max(1,min(int(timeout),int(max(1,self.max_seconds-self.elapsed()-3))))
        self.event('COMMAND_START',label=label,argv=[str(x) for x in argv])
        try:p=subprocess.run([str(x) for x in argv],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=timeout)
        except subprocess.TimeoutExpired:raise Stop('TIMEOUT',f'{label} timed out after {timeout}s')
        out=scrub(p.stdout or ''); (self.logs/f'{len(list(self.logs.iterdir())):03d}_{label}.log').write_text(out); print(out[-4000:],flush=True); self.event('COMMAND_END',label=label,returncode=p.returncode)
        if p.returncode not in ok:raise Stop('REMOTE_SERVICE',f'{label} rc={p.returncode}: {out[-1200:]}')
        return p.returncode,out
    def locate(self):
        require(self.py.is_file(),f'Project python missing: {self.py}','ENVIRONMENT')
        for p in (self.root/'.venv/bin/kaggle',Path(shutil.which('kaggle') or '/nonexistent')):
            if p.is_file() and os.access(p,os.X_OK):self.kaggle=p;break
        require(self.kaggle is not None,'Authenticated Kaggle CLI missing','ENVIRONMENT')
        self.cmd([self.kaggle,'--version'],'kaggle_version',30); _,h=self.cmd([self.kaggle,'competitions','submit','--help'],'submit_help',30); require('-v' in h and '-k' in h,'CLI lacks versioned code submission','ENVIRONMENT')
    def submissions(self,label):
        _,out=self.cmd([self.kaggle,'competitions','submissions',COMPETITION,'-v'],label,60); rows=parse_submission_csv(out); require(rows,'Could not parse submission inventory','REMOTE_SERVICE'); return rows
    def daily_count(self,rows):return sum(1 for r in rows if row_date(r).startswith(TODAY_UTC))
    def find_ref(self,rows,ref):return next((r for r in rows if row_ref(r)==str(ref)),None)
    def fetch_output(self,c):
        owner,slug=c['kernel'].split('/',1); snap=self.run/'candidates'/c['label']; target=snap/'submission.csv'; snap.mkdir(parents=True,exist_ok=True)
        _,out=self.cmd([self.py,'-c',FETCH_HELPER,owner,slug,str(c['version']),str(target)],'fetch_'+c['label']+'_output',180)
        line=next((x for x in out.splitlines() if x.startswith('BIOHUB_OUTPUT_FETCH ')),None); require(line,'Output helper receipt missing','REMOTE_SERVICE'); meta=json.loads(line.split(' ',1)[1])
        require('COMPLETE' in meta.get('status','').upper(),f"{c['label']} version {c['version']} not complete: {meta}",'SOURCE_STATE')
        st=validate_submission_file(target); oh=sha(target); rec={**c,'output_sha256':oh,'output_stats':st,'version_status':meta['status'],'distinct_from_anvith':oh!=ANVITH_OUTPUT_SHA,'verified_utc':utc()}; save(snap/'audit.json',rec); self.audit_records.append(rec); self.event('CANDIDATE_OUTPUT_AUDITED',**rec); return rec
    def submit(self,rec,seen_hashes,allowed_new):
        if rec['output_sha256'] in seen_hashes:
            self.event('CANDIDATE_SKIPPED_DUPLICATE_PREDICTIONS',label=rec['label'],output_sha256=rec['output_sha256']); return None
