        tag=candidate_tag(rec['label'],rec['output_sha256']); prior=next((r for r in rows if tag in row_desc(r)),None)
        if prior:
            state={'ref':row_ref(prior),'status':row_status(prior),'score':row_score(prior),'description':row_desc(prior),'date':row_date(prior),'created':False}; self.event('DUPLICATE_GUARD_REUSED_EXISTING',**state); seen_hashes.add(rec['output_sha256']); return state
        require(count < MAX_DAILY_SUBMISSIONS-RESERVE_DAILY_SLOTS,f'Daily submission reserve exhausted: {count}/{MAX_DAILY_SUBMISSIONS}','SUBMISSION_LIMIT')
        require(len(self.new_submissions)<allowed_new,'Per-run submission allowance exhausted','SUBMISSION_LIMIT')
        msg=tag+' | published 0.953 saved version; output-diverse vs prior 0.953 submissions'
        argv=[self.kaggle,'competitions','submit',COMPETITION,'-f',OUTPUT_FILENAME,'-k',rec['kernel'],'-v',str(rec['version']),'-m',msg]
        rc,out=self.cmd(argv,'submit_'+rec['label'],120,ok=(0,1,2,3,4,5)); m=re.search(r'Submission\s+ref\s*:\s*(\d+)',out,re.I); ref=m.group(1) if m else None
        after=self.submissions('submissions_after_'+rec['label']); tagged=next((r for r in after if tag in row_desc(r)),None); ref=ref or (row_ref(tagged) if tagged else None)
        if not ref:
            self.event('PUBLIC_CANDIDATE_SUBMISSION_BLOCKED',label=rec['label'],returncode=rc,tail=out[-700:]); return {'blocked':True,'label':rec['label'],'created':False}
        state={'ref':str(ref),'status':row_status(tagged) if tagged else 'PENDING','score':row_score(tagged) if tagged else None,'description':row_desc(tagged) if tagged else msg,'date':row_date(tagged) if tagged else '', 'created':True,'label':rec['label'],'output_sha256':rec['output_sha256']}
        self.new_submissions.append(state); seen_hashes.add(rec['output_sha256']); save(self.run/f'submission_{ref}_accepted.json',state); self.event('DIVERSE_SUBMISSION_ACCEPTED',**state); return state
    def execute(self):
        require(self.root.is_dir(),f'Project root missing: {self.root}','PATH'); self.locate(); before=self.submissions('submissions_before'); count=self.daily_count(before); allowed=allowed_new_slots(count)
        require(allowed>0,f'No submission slots available while reserving {RESERVE_DAILY_SLOTS}: daily={count}','SUBMISSION_LIMIT'); self.event('DAILY_SLOT_PLAN',daily_count=count,allowed_new_this_run=allowed,reserved_for_hoct=RESERVE_DAILY_SLOTS)
        anv=self.find_ref(before,ANVITH_REF); anv_state=None
        if anv:
            anv_state={'ref':row_ref(anv),'status':row_status(anv),'score':row_score(anv),'description':row_desc(anv),'date':row_date(anv)}; save(self.run/'anvith_56687425_state.json',anv_state); self.event('ANVITH_REFERENCE_STATE',**anv_state)
        seen={ANVITH_OUTPUT_SHA}; outcomes=[]
        for c in CANDIDATES:
            self.budget(); rec=self.fetch_output(c)
            try:state=self.submit(rec,seen,allowed)
            except Stop as e:
                if e.kind in ('PUBLIC_KERNEL_SUBMISSION_BLOCKED','REMOTE_SERVICE'):
                    outcomes.append({'label':c['label'],'blocked':True,'error':str(e)}); continue
                raise
            if state:outcomes.append(state)
            if len(self.new_submissions)>=allowed:break
        final_rows=self.submissions('submissions_final'); final_states=[]
        for s in self.new_submissions:
            r=self.find_ref(final_rows,s['ref']); final_states.append({'ref':s['ref'],'label':s['label'],'status':row_status(r) if r else s['status'],'score':row_score(r) if r else s['score'],'output_sha256':s['output_sha256']})
        anv_final=self.find_ref(final_rows,ANVITH_REF); anv_score=row_score(anv_final) if anv_final else (anv_state or {}).get('score'); best=max([x for x in [anv_score]+[x['score'] for x in final_states] if x is not None],default=None)
        if self.new_submissions:
            decision='public0953_diverse_submissions_accepted'; terminal='SUCCESS' if best is not None and best>=0.953-1e-12 else 'STOPPED'
        else:
            decision='no_new_output_diverse_public0953__move_to_hoct'; terminal='STOPPED'
        return {'terminal':terminal,'decision':decision,'official_public_score':best,'anvith_state':{'ref':ANVITH_REF,'score':anv_score,'status':row_status(anv_final) if anv_final else None},'new_submission_states':final_states,'audits':self.audit_records,'outcomes':outcomes,'reserved_daily_slots':RESERVE_DAILY_SLOTS}
    def package(self,final):
        final={**final,'version':VERSION,'run_id':self.run_id,'elapsed_seconds':round(self.elapsed(),3),'estimated_instance_cost_usd':round(self.elapsed()/3600*RATE,6),'new_kaggle_submissions':len(self.new_submissions),'finished_utc':utc()}; save(self.run/'final_receipt.json',final); save(self.run/'events.json',self.events)
        ret=self.root.parent/RETURN_NAME; tmp=ret.with_name(ret.name+'.partial')
