class Stop(RuntimeError):
    def __init__(self, kind: str, msg: str): self.kind=kind; super().__init__(msg)

def require(ok, msg, kind="INTEGRITY"):
    if not ok: raise Stop(kind,msg)

def utc(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")

def sha(path: Path) -> str:
    h=hashlib.sha256()
    with Path(path).open("rb") as f:
        for b in iter(lambda:f.read(1<<20), b""): h.update(b)
    return h.hexdigest()

def save(path: Path, obj):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    require(not path.is_symlink(), "Refusing output symlink", "PATH")
    tmp=path.with_name(path.name+".partial")
    data=(json.dumps(obj,indent=2,sort_keys=True,allow_nan=False)+"\n").encode()
    with tmp.open("wb") as f: f.write(data); f.flush(); os.fsync(f.fileno())
    os.replace(tmp,path)

def nb_code_hash(path: Path) -> dict:
    nb=json.loads(Path(path).read_text())
    cells=[]
    for c in nb.get("cells",[]):
        if c.get("cell_type") != "code": continue
        src=c.get("source","")
        cells.append("".join(src) if isinstance(src,list) else str(src))
    return {
        "count":len(cells),
        "cells_nul":hashlib.sha256("\n\0\n".join(cells).encode()).hexdigest(),
        "cells_double_newline":hashlib.sha256("\n\n".join(cells).encode()).hexdigest(),
    }

def scrub(s: str) -> str:
    s=str(s)
    s=re.sub(r"(?i)(authorization\s*[:=]\s*)([^\r\n]+)",r"\1[REDACTED]",s)
    s=re.sub(r"(?i)((?:token|api[_-]?key|password|x-amz-signature|x-amz-credential)=)[^\s&]+",r"\1[REDACTED]",s)
    return s

def parse_submission_csv(text: str):
    lines=[ln for ln in text.splitlines() if ln.strip()]
    start=None
    for i,ln in enumerate(lines):
        low=ln.lower().replace(" ","")
        if low.startswith("ref,") and "status" in low:
            start=i; break
    if start is None: return []
    return list(csv.DictReader(io.StringIO("\n".join(lines[start:]))))

def row_ref(r):
    for k in ("ref","Ref","reference","submissionRef"):
        if r.get(k): return str(r[k]).strip()
    return ""

def row_desc(r):
    for k in ("description","Description","message","Message"):
        if r.get(k): return str(r[k])
    return ""

def row_status(r):
    for k in ("status","Status"):
        if r.get(k): return str(r[k]).upper()
    return ""

def row_score(r):
    for k in ("publicScore","public_score","Public Score","score"):
        v=r.get(k)
        if v not in (None,""):
            try: return float(v)
            except Exception: pass
    return None

def find_tag(rows):
    hits=[r for r in rows if TAG in row_desc(r)]
    return hits[0] if hits else None

class Runner:
    def __init__(self, root: Path, max_seconds: int, max_cost: float):
        self.root=Path(root).resolve(); self.max_seconds=max_seconds; self.max_cost=max_cost
        self.start=time.monotonic(); self.state=self.root/STATE_REL
        self.run_id=datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")+"_"+os.urandom(3).hex()
        self.run=self.state/"runs"/self.run_id; self.logs=self.run/"logs"; self.logs.mkdir(parents=True,exist_ok=True)
        self.events=[]; self.submission_ref=None; self.new_submission=0; self.kaggle=None; self.py=self.root/".venv/bin/python"; self.public_version=None
    def elapsed(self): return time.monotonic()-self.start
    def budget(self):
        e=self.elapsed(); require(e < self.max_seconds, f"Runtime budget exhausted at {e:.1f}s", "TIMEOUT")
        cost=e/3600*RATE; require(cost <= self.max_cost+1e-9, f"Cost budget exhausted at ${cost:.4f}", "COST")
    def event(self, stage, **kw):
        rec={"utc":utc(),"elapsed_seconds":round(self.elapsed(),3),"stage":stage,**kw}; self.events.append(rec)
        print(f"[{rec['utc']}] {stage} elapsed={rec['elapsed_seconds']}s", flush=True)
        if kw: print(scrub(json.dumps(kw,sort_keys=True)), flush=True)
    def cmd(self, argv, label, timeout=120, ok=(0,)):
        self.budget(); timeout=max(1,min(timeout,int(max(1,self.max_seconds-self.elapsed()-3))))
        self.event("COMMAND_START",label=label,argv=[str(x) for x in argv])
        p=subprocess.run([str(x) for x in argv],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=timeout)
        out=scrub(p.stdout or "")
        (self.logs/f"{len(list(self.logs.iterdir())):03d}_{label}.log").write_text(out)
        print(out[-4000:],flush=True)
        self.event("COMMAND_END",label=label,returncode=p.returncode)
        if p.returncode not in ok: raise Stop("REMOTE_SERVICE",f"{label} rc={p.returncode}: {out[-1200:]}")
        return p.returncode,out
    def locate_kaggle(self):
        candidates=[self.root/".venv/bin/kaggle", Path(shutil.which("kaggle") or "/nonexistent")]
        for p in candidates:
            if p.is_file() and os.access(p,os.X_OK):
                self.kaggle=p; break
        require(self.kaggle is not None,"Authenticated Kaggle CLI executable not found","ENVIRONMENT")
        _,v=self.cmd([self.kaggle,"--version"],"kaggle_version",30)
        _,h=self.cmd([self.kaggle,"competitions","submit","--help"],"submit_help",30)
        require("--kernel" in h or "-k" in h,"Installed Kaggle CLI lacks code-competition --kernel submit support","ENVIRONMENT")
        self.event("KAGGLE_READY",version=v.strip(),path=str(self.kaggle))
    def submissions(self, label="submissions"):
        _,out=self.cmd([self.kaggle,"competitions","submissions",COMPETITION,"-v"],label,60)
        rows=parse_submission_csv(out)
        require(rows,"Could not parse authenticated competition submission inventory","REMOTE_SERVICE")
        return rows
    def verify_public_latest(self):
        snap=self.run/"public_latest"; src=snap/"source"; outdir=snap/"output"
        src.mkdir(parents=True); outdir.mkdir(parents=True)
        self.cmd([self.kaggle,"kernels","pull",PUBLIC_KERNEL,"-p",src,"-m"],"pull_public_source",120)
        notebooks=list(src.glob("*.ipynb"))
        require(len(notebooks)==1,f"Expected exactly one pulled notebook, found {len(notebooks)}","SOURCE_STATE")
        nh=nb_code_hash(notebooks[0]); require(nh["cells_nul"]==EXPECTED_CODE_NUL_SHA,
            f"Public latest executable code changed: {nh['cells_nul']} != {EXPECTED_CODE_NUL_SHA}","SOURCE_STATE")
        self.cmd([self.kaggle,"kernels","output",PUBLIC_KERNEL,"-p",outdir,"-o"],"pull_public_output",180)
        candidates=[p for p in outdir.rglob(OUTPUT_FILENAME) if p.is_file()]
        require(len(candidates)==1,f"Expected one {OUTPUT_FILENAME} in public output, found {len(candidates)}","SOURCE_STATE")
        oh=sha(candidates[0]); require(oh==EXPECTED_PUBLIC_OUTPUT_SHA,
            f"Public latest output changed: {oh} != {EXPECTED_PUBLIC_OUTPUT_SHA}","SOURCE_STATE")
        rec={"kernel":PUBLIC_KERNEL,"source_file":notebooks[0].name,"source_file_sha256":sha(notebooks[0]),
             "code_hashes":nh,"output_sha256":oh,"output_bytes":candidates[0].stat().st_size,"verified_utc":utc()}
        save(self.run/"public_latest_verified.json",rec); self.event("PUBLIC_0953_SNAPSHOT_VERIFIED",**rec)

    def resolve_public_version(self):
        require(self.py.is_file(), f"Project Python missing: {self.py}", "ENVIRONMENT")
        helper = r'''
import hashlib, json
from kaggle.api.kaggle_api_extended import KaggleApi
from kagglesdk.kernels.types.kernels_api_service import ApiGetKernelRequest, ApiListKernelSessionOutputRequest, ApiGetKernelSessionStatusRequest
OWNER="anvithpothula"
SLUG="biohub-0-953-lb-original"
a=KaggleApi(); a.authenticate()
with a.build_kaggle_client() as kg:
    q=ApiGetKernelRequest(); q.user_name=OWNER; q.kernel_slug=SLUG
    latest=kg.kernels.kernels_api_client.get_kernel(q)
    n=int(latest.metadata.current_version_number)
    qv=ApiGetKernelRequest(); qv.user_name=OWNER; qv.kernel_slug=SLUG; qv.version_label=f"v{n}"
    v=kg.kernels.kernels_api_client.get_kernel(qv)
    src=v.blob.source
    nb=json.loads(src)
    cells=[]
    for c in nb.get("cells",[]):
        if c.get("cell_type")!="code": continue
        x=c.get("source",""); cells.append("".join(x) if isinstance(x,list) else str(x))
    nul=hashlib.sha256("\n\0\n".join(cells).encode()).hexdigest()
    raw=hashlib.sha256(src.encode()).hexdigest()
    names=[]; token=None
    for _ in range(20):
        o=ApiListKernelSessionOutputRequest(); o.user_name=OWNER; o.kernel_slug=SLUG; o.version_label=f"v{n}"; o.page_size=200
        if token: o.page_token=token
        rr=kg.kernels.kernels_api_client.list_kernel_session_output(o)
        names.extend([x.file_name for x in (rr.files or [])])
        token=rr.next_page_token
        if not token: break
    st=ApiGetKernelSessionStatusRequest(); st.user_name=OWNER; st.kernel_slug=SLUG; st.version_label=f"v{n}"
    sr=kg.kernels.kernels_api_client.get_kernel_session_status(st)
print("BIOHUB_PUBLIC_VERSION_JSON "+json.dumps({"current_version_number":n,"version_label":f"v{n}","code_cells":len(cells),"code_nul_sha256":nul,"source_text_sha256":raw,"output_count":len(names),"has_submission_csv":"submission.csv" in names,"status":str(sr.status),"failure_message":str(sr.failure_message or "")},sort_keys=True))
'''
        _,out=self.cmd([self.py,"-c",helper],"resolve_public_current_version",90)
        marker="BIOHUB_PUBLIC_VERSION_JSON "
        line=next((x for x in out.splitlines() if x.startswith(marker)),None)
        require(line is not None,"Could not parse public kernel current version from authenticated Kaggle SDK","REMOTE_SERVICE")
        try: rec=json.loads(line[len(marker):])
        except Exception as e: raise Stop("REMOTE_SERVICE",f"Invalid current-version JSON: {e}")
        n=rec.get("current_version_number")
        require(isinstance(n,int) and n>=1,f"Invalid current version number: {n!r}","SOURCE_STATE")
        require(rec.get("code_nul_sha256")==EXPECTED_CODE_NUL_SHA,
                f"Version v{n} executable hash changed: {rec.get('code_nul_sha256')} != {EXPECTED_CODE_NUL_SHA}","SOURCE_STATE")
        require(rec.get("has_submission_csv") is True,f"Version v{n} has no submission.csv output","SOURCE_STATE")
        require("COMPLETE" in str(rec.get("status","")).upper(),f"Version v{n} is not COMPLETE: {rec.get('status')}","SOURCE_STATE")
        self.public_version=n
        save(self.run/"public_version_verified.json",rec)
        self.event("PUBLIC_0953_VERSION_VERIFIED",**rec)
        return n

    def poll_ref(self, ref, seconds):
        deadline=min(time.monotonic()+seconds,self.start+self.max_seconds-5)
        last=None
        while time.monotonic()<deadline:
            self.budget(); rows=self.submissions("poll_submissions")
            row=next((r for r in rows if row_ref(r)==str(ref)),None)
            if row:
                last={"ref":row_ref(row),"status":row_status(row),"score":row_score(row),"description":row_desc(row)}
                save(self.run/"latest_submission_state.json",last)
                self.event("SUBMISSION_STATE",**last)
                if "COMPLETE" in last["status"] or "ERROR" in last["status"] or "FAIL" in last["status"]:
                    return last
            sleep=min(30,max(1,deadline-time.monotonic()))
            if sleep>0: time.sleep(sleep)
        return last or {"ref":str(ref),"status":"PENDING_OR_UNKNOWN","score":None,"description":MESSAGE}
    def execute(self):
        require(self.root.is_dir(),f"Project root missing: {self.root}","PATH")
        require(self.max_seconds>=60,"max-seconds too small","CONFIG")
        require(self.max_cost>0,"max-cost-usd must be positive","CONFIG")
        self.locate_kaggle()
        before=self.submissions("submissions_before")
        prior=find_tag(before)
        if prior:
            ref=row_ref(prior); require(ref,"Duplicate-tag row lacks ref","REMOTE_SERVICE")
            self.submission_ref=ref; self.event("DUPLICATE_GUARD_REUSED_EXISTING",ref=ref,status=row_status(prior),score=row_score(prior))
            state=self.poll_ref(ref,min(180,int(self.max_seconds-self.elapsed()-10)))
            return self.decide(state, reused=True)
        # Freshness and exact-public-snapshot gates occur before any write.
        self.verify_public_latest()
        version=self.resolve_public_version()
        # Re-read immediately before the write in case another terminal/process submitted meanwhile.
        prior=find_tag(self.submissions("submissions_prewrite"))
        if prior:
            ref=row_ref(prior); self.submission_ref=ref; self.event("DUPLICATE_GUARD_RACE_REUSED",ref=ref)
            state=self.poll_ref(ref,min(180,int(self.max_seconds-self.elapsed()-10)))
            return self.decide(state,reused=True)
        argv=[self.kaggle,"competitions","submit",COMPETITION,"-f",OUTPUT_FILENAME,"-k",PUBLIC_KERNEL,"-v",str(version),"-m",MESSAGE]
        rc,out=self.cmd(argv,"direct_public_kernel_submit",120,ok=(0,1,2,3,4,5))
        m=re.search(r"Submission\s+ref\s*:\s*(\d+)",out,re.I)
        ref=m.group(1) if m else None
        after=self.submissions("submissions_after_submit")
        tagged=find_tag(after)
        if tagged and not ref: ref=row_ref(tagged)
        if not ref:
            # No server-created submission => do not try a clone with broken latest support inputs.
            save(self.run/"direct_submit_blocked.json",{"returncode":rc,"output_tail":out[-3000:],"utc":utc(),
                "public_version":version,"decision":"public_saved_kernel_versioned_submission_blocked__move_to_hoct_frozen_detection_ab"})
            raise Stop("PUBLIC_KERNEL_DIRECT_SUBMISSION_BLOCKED",
                f"Kaggle did not create a submission from exact public 0.953 kernel version v{version}. Do not clone against the changed latest support pack. Next decision: HOCT frozen-detection A/B.")
        self.submission_ref=ref; self.new_submission=1; self.event("SUBMISSION_ACCEPTED",ref=ref)
        remaining=max(20,min(240,int(self.max_seconds-self.elapsed()-10)))
        state=self.poll_ref(ref,remaining)
        return self.decide(state,reused=False)
    def decide(self,state,reused=False):
        score=state.get("score"); status=state.get("status","")
        if score is not None and "COMPLETE" in status:
            if score >= 0.953-1e-12:
                return {"terminal":"SUCCESS","decision":"public_0953_recreated_as_official_submission","official_public_score":score,"submission_ref":state["ref"],"reused":reused}
            return {"terminal":"STOPPED","decision":"exact_public_kernel_scored_below_0953","official_public_score":score,"submission_ref":state["ref"],"reused":reused}
        if "ERROR" in status or "FAIL" in status:
            return {"terminal":"FAILED","decision":"kaggle_scoring_failed","official_public_score":score,"submission_ref":state["ref"],"reused":reused}
        return {"terminal":"STOPPED","decision":"submission_accepted_scoring_pending","official_public_score":score,"submission_ref":state["ref"],"reused":reused}
    def package(self, final):
        final={**final,"version":VERSION,"run_id":self.run_id,"elapsed_seconds":round(self.elapsed(),3),
               "estimated_instance_cost_usd":round(self.elapsed()/3600*RATE,6),"new_kaggle_submissions":self.new_submission,
               "public_kernel":PUBLIC_KERNEL,"public_version":self.public_version,"expected_public_output_sha256":EXPECTED_PUBLIC_OUTPUT_SHA,"finished_utc":utc()}
        save(self.run/"final_receipt.json",final); save(self.run/"events.json",self.events)
        ret=self.root.parent/RETURN_NAME
        tmp=ret.with_name(ret.name+".partial")
        with zipfile.ZipFile(tmp,"w",zipfile.ZIP_DEFLATED) as z:
            for p in sorted(self.run.rglob("*")):
                if p.is_file() and "public_latest" not in p.parts:
                    z.write(p,p.relative_to(self.run))
        os.replace(tmp,ret)
        return ret,final

