class Tests(unittest.TestCase):
    def test_nb_hash_formula(self):
        with tempfile.TemporaryDirectory() as d:
            p=Path(d)/"x.ipynb"; p.write_text(json.dumps({"cells":[{"cell_type":"code","source":["a\n"]},{"cell_type":"markdown","source":"x"},{"cell_type":"code","source":"b"}]}))
            got=nb_code_hash(p); self.assertEqual(got["count"],2); self.assertEqual(got["cells_nul"],hashlib.sha256("a\n\n\0\nb".encode()).hexdigest())
    def test_parse_inventory(self):
        t="noise\nref,fileName,date,description,status,publicScore,privateScore\n12,submission.csv,d,hello,SubmissionStatus.COMPLETE,0.953,\n"
        r=parse_submission_csv(t); self.assertEqual(row_ref(r[0]),"12"); self.assertEqual(row_score(r[0]),0.953); self.assertIn("COMPLETE",row_status(r[0]))
    def test_tag(self):
        r=[{"ref":"4","description":"x"},{"ref":"5","description":MESSAGE}]; self.assertEqual(row_ref(find_tag(r)),"5")
    def test_submit_argv_contract(self):
        argv=["kaggle","competitions","submit",COMPETITION,"-f",OUTPUT_FILENAME,"-k",PUBLIC_KERNEL,"-v","7","-m",MESSAGE]
        self.assertEqual(argv[argv.index("-k")+1],PUBLIC_KERNEL); self.assertEqual(argv[argv.index("-f")+1],"submission.csv")
        self.assertEqual(argv[argv.index("-v")+1],"7")
    def test_message_unique(self): self.assertIn(EXPECTED_PUBLIC_OUTPUT_SHA[:12],TAG)
    def test_score_gate(self):
        r=Runner.__new__(Runner)
        self.assertEqual(Runner.decide(r,{"score":0.953,"status":"COMPLETE","ref":"1"})["terminal"],"SUCCESS")
        self.assertEqual(Runner.decide(r,{"score":0.952,"status":"COMPLETE","ref":"1"})["terminal"],"STOPPED")
        self.assertEqual(Runner.decide(r,{"score":None,"status":"PENDING","ref":"1"})["decision"],"submission_accepted_scoring_pending")
    def test_execute_accepts_exactly_one_submission(self):
        class Fake(Runner):
            def locate_kaggle(self): self.kaggle=Path("/fake/kaggle")
            def verify_public_latest(self): self.event("PUBLIC_0953_SNAPSHOT_VERIFIED",fixture=True)
            def resolve_public_version(self): self.public_version=7; return 7
            def submissions(self,label="submissions"):
                if label=="submissions_after_submit":
                    return [{"ref":"777","description":MESSAGE,"status":"SubmissionStatus.PENDING","publicScore":""}]
                return []
            def cmd(self,argv,label,timeout=120,ok=(0,)):
                if label=="direct_public_kernel_submit":
                    self._submit_calls=getattr(self,"_submit_calls",0)+1
                    return 0,"Submission ref: 777\n"
                raise AssertionError(label)
            def poll_ref(self,ref,seconds): return {"ref":str(ref),"status":"COMPLETE","score":0.953,"description":MESSAGE}
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)/"project"; root.mkdir()
            r=Fake(root,600,1.0); out=r.execute()
            self.assertEqual(out["terminal"],"SUCCESS"); self.assertEqual(out["submission_ref"],"777")
            self.assertEqual(r._submit_calls,1); self.assertEqual(r.new_submission,1)
    def test_execute_blocked_cross_owner_has_no_submission(self):
        class Fake(Runner):
            def locate_kaggle(self): self.kaggle=Path("/fake/kaggle")
            def verify_public_latest(self): pass
            def resolve_public_version(self): self.public_version=7; return 7
            def submissions(self,label="submissions"): return []
            def cmd(self,argv,label,timeout=120,ok=(0,)):
                if label=="direct_public_kernel_submit": return 1,"403 permission denied\n"
                raise AssertionError(label)
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)/"project"; root.mkdir(); r=Fake(root,600,1.0)
            with self.assertRaises(Stop) as cm: r.execute()
            self.assertEqual(cm.exception.kind,"PUBLIC_KERNEL_DIRECT_SUBMISSION_BLOCKED")
            self.assertEqual(r.new_submission,0)

    def test_resolve_version_accepts_hash_complete_and_output(self):
        class Fake(Runner):
            def cmd(self,argv,label,timeout=120,ok=(0,)):
                rec={"current_version_number":7,"version_label":"v7","code_cells":12,"code_nul_sha256":EXPECTED_CODE_NUL_SHA,"source_text_sha256":"x","output_count":3,"has_submission_csv":True,"status":"KernelWorkerStatus.COMPLETE","failure_message":""}
