        class Fake(Runner):
            def cmd(self,argv,label,timeout=120,ok=(0,)):
                rec={"current_version_number":7,"code_nul_sha256":"bad","has_submission_csv":True,"status":"COMPLETE"}
                return 0,"BIOHUB_PUBLIC_VERSION_JSON "+json.dumps(rec)+"\n"
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)/"project"; (root/".venv/bin").mkdir(parents=True); (root/".venv/bin/python").write_text("")
            r=Fake(root,600,1.0)
            with self.assertRaises(Stop) as cm: r.resolve_public_version()
            self.assertEqual(cm.exception.kind,"SOURCE_STATE")

    def test_duplicate_guard_never_resubmits(self):
        class Fake(Runner):
            def locate_kaggle(self): self.kaggle=Path("/fake/kaggle")
            def submissions(self,label="submissions"):
                return [{"ref":"888","description":MESSAGE,"status":"SubmissionStatus.PENDING","publicScore":""}]
            def poll_ref(self,ref,seconds): return {"ref":str(ref),"status":"COMPLETE","score":0.953,"description":MESSAGE}
            def verify_public_latest(self): raise AssertionError("should not run after duplicate")
            def cmd(self,*a,**k): raise AssertionError("submit should not run")
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)/"project"; root.mkdir(); r=Fake(root,600,1.0); out=r.execute()
            self.assertEqual(out["terminal"],"SUCCESS"); self.assertTrue(out["reused"]); self.assertEqual(r.new_submission,0)

def self_test():
    suite=unittest.defaultTestLoader.loadTestsFromTestCase(Tests); res=unittest.TextTestRunner(verbosity=2).run(suite)
    if not res.wasSuccessful(): raise SystemExit(20)
    print("BIOHUB_PUBLIC0953_VERSIONED_SUBMIT_SELF_TEST_PASSED")
    print("EXACT_PUBLIC_SOURCE_OUTPUT_AND_VERSION_GATE_ENABLED")
    print("ONE_SUBMISSION_MAX_WITH_DUPLICATE_GUARD")
    print("NO_LOCAL_CSV_COMPETITION_UPLOAD")
    print("NO_KERNEL_PUSH_OR_CLONE")
    print("AUTHENTICATED_CURRENT_VERSION_DISCOVERY_ENABLED")
    print("NO_MODEL_FITS")

def main(argv=None):
    ap=argparse.ArgumentParser(); ap.add_argument("--root",default="/home/sagemaker-user/biohub-cell-tracking-during-development")
    ap.add_argument("--max-seconds",type=int,default=600); ap.add_argument("--max-cost-usd",type=float,default=0.28); ap.add_argument("--self-test",action="store_true")
    a=ap.parse_args(argv)
    if a.self_test: self_test(); return 0
    self_test(); r=Runner(Path(a.root),a.max_seconds,a.max_cost_usd)
    final={"terminal":"FAILED","decision":"uninitialized","official_public_score":None,"submission_ref":None}
    rc=1
    try:
        final=r.execute(); rc=0 if final["terminal"] in ("SUCCESS","STOPPED") else 1
    except Stop as e:
        final={"terminal":"STOPPED" if e.kind in ("PUBLIC_KERNEL_DIRECT_SUBMISSION_BLOCKED","SOURCE_STATE","REMOTE_SERVICE") else "FAILED",
               "decision":e.kind.lower(),"error":str(e),"official_public_score":None,"submission_ref":r.submission_ref}
