        if z.testzip():raise RuntimeError('Outer ZIP CRC failed')
        manifest=json.loads(z.read('manifest.json'));raw=z.read('payload.zip')
    if hashlib.sha256(raw).hexdigest()!=manifest['payload_sha256']:raise RuntimeError('Payload SHA256 mismatch')
    dest=Path(target)/manifest['payload_sha256'][:16]
    dest.mkdir(parents=True,exist_ok=True)
    if dest.is_symlink():raise RuntimeError('Unsafe extraction path')
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        if z.testzip() or len(z.namelist())!=len(set(z.namelist())) or set(z.namelist())!=set(manifest['files']):raise RuntimeError('Payload member/CRC mismatch')
        for n,h in manifest['files'].items():
            if Path(n).is_absolute() or '..' in Path(n).parts:raise RuntimeError('Unsafe payload member')
            b=z.read(n);p=dest/n
            if hashlib.sha256(b).hexdigest()!=h:raise RuntimeError('Member hash mismatch '+n)
            if p.is_symlink() or not p.resolve().is_relative_to(dest.resolve()):raise RuntimeError('Unsafe payload destination')
            if p.exists() and p.read_bytes()!=b:raise RuntimeError('Extracted code changed '+n)
            p.parent.mkdir(parents=True,exist_ok=True)
