def finish(root,out,info,invoke,submit=False):
    root,out=Path(root),Path(out);out.mkdir(parents=True,exist_ok=True)
    calls=[]
    def call(op,**kw):
        calls.append(op);save(out/'operation_log.json',{'operations':calls})
        return invoke({'op':op,**kw})
    def check_existing():
        r=call('submissions');require(r.get('complete') is True,'Incomplete submission inventory','SDK_PROTOCOL')
        rows=r.get('submissions');require(isinstance(rows,list),'Malformed submissions response','SDK_PROTOCOL')
        matches=[s for s in rows if matches_submission(s)]
        return matches
    def found(matches):
        summaries=[submission_summary(x) for x in matches]
        result={'decision':'already_submitted','submissions':summaries,'kaggle_write_calls':0}
        if len(summaries)>1:result['warning']='Multiple pre-existing matching records; no further submission.'
        return result
    call('preflight')
    existing=check_existing()
    if existing:return found(existing)
    # Respect every prior mutation intent, even an unknown-outcome legacy write.
    old_intent=root/OLD_REL/'submission_intent.json'
    legacy=read(root/DELIVERY_REL/'remote_state.json')
    own=out/'submission_intent.json'
    if old_intent.is_file() or legacy.get('submit',{}).get('intent') or own.is_file():
        return {'decision':'existing_submission_intent_requires_reconciliation','kaggle_write_calls':0,
                'reason':'No matching record yet; do not retry a possibly successful write.'}
    state=call('status');status=normalize_status(state['status']);save(out/'remote_status.json',state)
    if status in ('RUNNING','QUEUED','PENDING'):
        # Exactly one status observation and one bounded log-tail read, no paid idle loop.
        try:
            save(out/'remote_progress.json',call('logs'))
        except Exception as e:save(out/'remote_progress.json',{'logs_unavailable':scrub(e)})
        return {'decision':'existing_submission_notebook_still_running','remote_status':status,'kaggle_write_calls':0,'poll_loop':False}
    if status in ('ERROR','CANCELLED'):
        try:logs=call('logs')
        except Exception as e:logs={'read_error':scrub(e)}
        save(out/'remote_failure.json',{'status':status,'logs':logs})
        raise Stop('REMOTE_EXECUTION','Existing version 1 ended '+status+'; saved diagnostics; no repush or submit')
    require(status=='COMPLETE','No complete fixed version','STATUS_PROTOCOL')
    source=out/'pinned_source_v1'
    source_ok=False;source_proof=None;launch=None
    if (source/'verification.json').is_file():
        # A previously accessible source never silently changes evidence routes.
        source_proof=verify_saved_notebook(source,info);source_ok=True
    if not source_ok:
        if source.exists():source=out/('pinned_source_v1_recovery_'+str(time.time_ns()))
        source_response=call('source',directory=str(source))
        require(source_response.get('ref_used')==REF,'Source request not version-pinned','IDENTITY')
        if source_response.get('available') is False:
            require(source_response.get('http_status')==403 and source_response.get('reason')=='source_read_denied',
                    'Unexpected source response; no fallback','IDENTITY')
            source_proof=source_response
            save(out/'source_read_unavailable.json',source_response)
            launch=local_launch(root,info)
            save(out/'original_launch_identity.json',launch)
        else:
            source_proof=verify_saved_notebook(source,info)
    if source_proof.get('status')=='passed':
        meta=read(safe_file(source,'kernel-metadata.json'))
        require(meta.get('competition_sources')==[COMPETITION],'Saved competition input differs','DELIVERY')
        require(meta.get('enable_internet') in (False,'false'),'Saved submission must run offline','DELIVERY')
        save(source/'verification.json',source_proof)
    directory=out/'verified_output_v1';proof=None
    marker=out/'output_location.json'
    if marker.is_file():
        p=read(marker).get('path');candidate=Path(p) if isinstance(p,str) else directory
        require(candidate.resolve().is_relative_to(out.resolve()),'Unsafe cached output location','SOURCE_STATE')
        directory=candidate
    if (directory/'verification.json').is_file():
        try:
            verify_download(directory,out,info)
            proof=verify_output(directory,info)
        except Exception:
            directory=out/('verified_output_v1_recovery_'+str(time.time_ns()))
    if proof is None:
        response=call('output',directory=str(directory))
        record_download(directory,out,info,response)
        proof=verify_output(directory,info)
    save(directory/'verification.json',proof);save(marker,{'path':str(directory)})
    save(out/'output_verification.json',proof)
    identity=reconcile_identity(source_proof,launch,verify_download(directory,out,info),proof,info)
    save(out/'submission_identity_verification.json',identity)
    result={'output':proof,'saved_source':source_proof,'identity':identity,'kaggle_write_calls':0}
    if not submit:return {'decision':'verified_output_ready_for_submission',**result}
    existing=check_existing()
    if existing:return {**found(existing),'output':proof}
    # Persist intent atomically before the only remote write. Never overwrite an intent.
    require(not own.exists(),'An intent appeared concurrently','CONCURRENCY')
    save(own,{'kernel':KERNEL,'version':1,'message':MESSAGE,'file':'submission.csv',
              'submission_sha256':proof['submission_sha256'],'notebook_sha256':info['notebook_sha256'],'identity_method':identity['method'],'state':'intent'})
    try:
        response=call('submit',authorized=True)
        save(out/'submit_response.json',response)
    except BaseException as e:
        save(out/'submit_ambiguity.json',{'error':scrub(e),'automatic_retry':False})
        return {'decision':'submission_outcome_ambiguous_reconcile_on_rerun','kaggle_write_calls':1,'output':proof}
    try:existing=check_existing()
    except Exception as e:
        existing=[];save(out/'readback_error.json',{'error':scrub(e)})
    raw=response.get('result',{})
    acknowledged=bool(get(raw,'ref','submission_id','id')) and not get(raw,'error')
    if not existing and not acknowledged:
        return {'decision':'submission_outcome_ambiguous_reconcile_on_rerun','kaggle_write_calls':1,'output':proof,'response':raw}
    saved={'status':'acknowledged','kernel':KERNEL,'version':1,'result':raw,'records':[submission_summary(x) for x in existing]}
    save(out/'submission_acknowledged.json',saved)
    return {'decision':'competition_submission_sent','kaggle_write_calls':1,'output':proof,'identity':identity,'submission':saved}

