from __future__ import annotations
import json, os, math, sys, subprocess, datetime
from pathlib import Path
RATES={'ml.g6e.xlarge':2.61,'ml.g6e.2xlarge':2.8,'ml.g6e.4xlarge':3.76,'ml.g6e.8xlarge':5.66,'ml.g6e.16xlarge':9.47}
CPUS={'ml.g6e.xlarge':4,'ml.g6e.2xlarge':8,'ml.g6e.4xlarge':16,'ml.g6e.8xlarge':32,'ml.g6e.16xlarge':64}
PRICE_OBSERVED_UTC='2026-09-29T00:57:27Z'
PRICE_PUBLICATION_UTC='2026-09-28T21:57:12Z'
GIB=1<<30

def plan(instance_type,requested_seconds,max_cost,available_bytes,total_bytes,cpu_count,rate=None):
    if instance_type not in RATES:raise RuntimeError('ENVIRONMENT_UNSUPPORTED_INSTANCE '+str(instance_type))
    rate=RATES[instance_type] if rate is None else float(rate)
    if not math.isfinite(rate) or rate<=0:raise RuntimeError('ENVIRONMENT_INVALID_RATE')
    if not math.isfinite(float(max_cost)) or float(max_cost)<=0:raise RuntimeError('BUDGET_INVALID_COST')
    if int(requested_seconds)<=0:raise RuntimeError('BUDGET_INVALID_SECONDS')
    seconds=min(int(requested_seconds),int(float(max_cost)*3600/rate))
    if seconds<45:raise RuntimeError('BUDGET_TOO_SMALL_FOR_PREFLIGHT')
    if total_bytes<=0 or available_bytes<0 or available_bytes>total_bytes:raise RuntimeError('MEMORY_INVALID_DISCOVERY')
    cpus=max(1,min(int(cpu_count),CPUS[instance_type]))
    workers=max(1,min(6,cpus//4,int(available_bytes//(8<<30))))
    rss_limit=int(min(.75*total_bytes,.85*available_bytes))
    return {'status':'passed','instance_type':instance_type,'rate_usd_per_hour':rate,
            'max_seconds':seconds,'max_compute_usd':seconds*rate/3600,
            'max_cost_usd_requested':max_cost,'cpu_count':cpus,'audit_workers':workers,
            'test_threads':1,'math_threads':1,
            'rss_limit_bytes':rss_limit,'available_bytes':available_bytes,'total_bytes':total_bytes,
            'gpu_processes':0,'gpu_memory_gb_expected':48,'region':'us-west-2',
            'instance_stopped_by_runner':False,'cloud_mutations':0}

def parse_meminfo(text):
    values={}
    for line in text.splitlines():
        k,sep,v=line.partition(':')
        if not sep:continue
        parts=v.split()
        if parts and parts[0].isdigit():values[k]=int(parts[0])*1024
    total=values.get('MemTotal',0)
    available=values.get('MemAvailable',values.get('MemFree',0)+values.get('Buffers',0)+values.get('Cached',0))
    if total<=0 or not 0<=available<=total:raise RuntimeError('MEMORY_PROC_MEMINFO_INVALID')
    return {'host_total_bytes':total,'host_available_bytes':available}

def system_memory():
    m=parse_meminfo(Path('/proc/meminfo').read_text())
    total=m['host_total_bytes'];available=m['host_available_bytes'];limit=None;current=None
