           (Path('/sys/fs/cgroup/memory/memory.limit_in_bytes'),Path('/sys/fs/cgroup/memory/memory.usage_in_bytes'))]
    for lp,cp in pairs:
        try:
            raw=lp.read_text().strip()
            if raw=='max':continue
            lim=int(raw);cur=int(cp.read_text().strip())
            if 0<lim<total:
