        except (OSError,ValueError):continue
    return {**m,'total_bytes':total,'available_bytes':available,'cgroup_limit_bytes':limit,'cgroup_current_bytes':current}

def parse_gpu_csv(text):
    rows=[]
    for line in text.splitlines():
        if not line.strip():continue
        parts=[s.strip() for s in line.split(',')]
        if len(parts)!=2:raise RuntimeError('ENVIRONMENT_NVIDIA_SMI_SCHEMA')
        try:memory_mib=float(parts[1])
        except ValueError:raise RuntimeError('ENVIRONMENT_NVIDIA_SMI_MEMORY') from None
        if not math.isfinite(memory_mib):raise RuntimeError('ENVIRONMENT_NVIDIA_SMI_MEMORY')
        rows.append({'name':parts[0],'memory_mib':memory_mib})
    return rows

def resolve_instance(host_cpus,host_total_bytes,gpus,declared='auto'):
    if len(gpus)!=1 or 'L40S' not in gpus[0]['name'].upper() or gpus[0]['memory_mib']<44000:
        raise RuntimeError('ENVIRONMENT_EXPECTED_ONE_48GB_L40S '+json.dumps(gpus))
    matches=[it for it,n in CPUS.items() if host_cpus==n and .85*(n*8*GIB)<=host_total_bytes<=1.05*(n*8*GIB)]
    if len(matches)!=1:
        raise RuntimeError('ENVIRONMENT_UNRECOGNIZED_G6E_CPU_RAM_PROFILE '+json.dumps({'host_cpus':host_cpus,'host_total_bytes':host_total_bytes,'matches':matches}))
    it=matches[0]
    if declared not in ('auto',it):raise RuntimeError('ENVIRONMENT_DECLARED_INSTANCE_MISMATCH '+str(declared)+' != '+it)
    return it

def read_local_hardware():
    m=system_memory()
    cpu_text=Path('/proc/cpuinfo').read_text()
    host_cpus=sum(1 for s in cpu_text.splitlines() if s.partition(':')[0].strip()=='processor') or (os.cpu_count() or 1)
    try:usable_cpus=len(os.sched_getaffinity(0))
    except (AttributeError,OSError):usable_cpus=os.cpu_count() or 1
    try:
        p=subprocess.run(['nvidia-smi','--query-gpu=name,memory.total','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=8)
