        return {'available':True,**{k:obj[k] for k in ('AppType','DomainId','SpaceName','ResourceArn','ResourceName','InstanceType') if k in obj}}
    except (OSError,ValueError) as e:return {'available':True,'parse_error':type(e).__name__}

