def make_output(folder,info):
    folder=Path(folder);folder.mkdir(parents=True,exist_ok=True)
    rows=[['0','fixture','node','1','0','1','2','3','-1','-1'],['1','fixture','node','2','1','1','2','4','-1','-1'],['2','fixture','node','3','1','1','2','5','-1','-1'],['3','fixture','edge','-1','-1','-1','-1','-1','1','2'],['4','fixture','edge','-1','-1','-1','-1','-1','1','3']]
    with (folder/'submission.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['id','dataset','row_type','node_id','t','z','y','x','source_id','target_id']);w.writerows(rows)
    digest=sha(folder/'submission.csv')
    save(folder/'winner_delivery_manifest.json',{'status':'complete','policy':'source_division_strict','submission_sha256':digest,'new_fits':0,'graphs':[{'dataset':'fixture','annotation_input':False,'policy':'source_division_strict','changes':{'nodes_preserved':True,'topology':'passed','added_edges':1,'removed_edges':1,'transactions':1}}]})
    save(folder/'winner_transport_receipt.json',{'status':'complete','asset_id':info['asset_id'],'files':info['files'],'qualified_notebook_sha256':info['original_notebook_sha256'],'inference_ast_unchanged':True})
    save(folder/'frozen_baseline_manifest.json',{'source_code_sha256':BASELINE_CODE,'training_validation_enabled':False,'postprocess_sweep_enabled':False,'resolved_configuration':{'MOTION_RELINK_TIGHT_UM':5.5}})
    save(folder/'dual_seed_frame_retention_guard_report.json',{'submission':{'datasets':['fixture'],'sha256':digest,'rows':5},'topology':{'fixture':{'nodes':3,'edges':2,'division_parents':1}}})
    save(folder/'winner_timing.json',[{'block':i,'status':'complete','seconds':.1} for i in range(10)])

class Fixture:
    def __init__(self,root,info,source=None):
        self.root=Path(root);self.info=info;self.source=source;self.status={'status':'COMPLETE'};self.ops=[];self.records=[];self.error=None
        save(self.root/DELIVERY_REL/'remote_state.json',{'kernel_push':{'status':'pushed','version':1}})
    def __call__(self,request):
        op=request['op'];self.ops.append(op)
        if self.error==op:raise Stop('REMOTE_SERVICE','injected '+op)
        if op=='preflight':return {}
        if op=='submissions':return {'complete':True,'submissions':self.records}
        if op=='status':return {'status':self.status,'ref_used':REF}
        if op=='logs':return {'logs':'fixture logs','ref_used':REF}
        if op=='source':
            dst=Path(request['directory']);dst.mkdir(parents=True,exist_ok=True)
            nb={'cells':[{'cell_type':'code','source':'print(1)'}]}
            save(dst/'n.ipynb',nb)
            save(dst/'kernel-metadata.json',{'id':KERNEL,'is_private':True,'enable_internet':False,'dataset_sources':[self.info['asset_id']],'competition_sources':[COMPETITION],'code_file':'n.ipynb'})
            return {'directory':str(dst),'ref_used':REF,'available':True}
        if op=='output':make_output(request['directory'],self.info);return {'directory':request['directory'],'ref_used':REF}
        if op=='submit':
            self.records.append({'ref':1234,'description':MESSAGE,'status':'PENDING'})
            return {'result':{'ref':1234,'error':None}}
        raise AssertionError(op)

class Base(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory();self.root=Path(self.tmp.name);self.out=self.root/'work'
        self.info=read(HERE/'expected_transport_proof.json');self.info['code_sha256']=code_digest({'cells':[{'cell_type':'code','source':'print(1)'}]})
    def tearDown(self):self.tmp.cleanup()
    def mutate(self,name,fn):
        p=self.out/name;r=read(p);fn(r);save(p,r)

class StatusTests(unittest.TestCase):
    def test_exact_return_envelope(self):
        x=read(HERE/'observed_status.json');self.assertEqual(normalize_status(x),'RUNNING')
    def test_old_str_dict_failure_reproduced(self):
        for x in ('RUNNING','COMPLETE','ERROR'):
            old=str({'status':x}).strip().split('.')[-1].upper();self.assertNotEqual(old,x)
    def test_typed_and_enum(self):
        class E(Enum):COMPLETE=1
        self.assertEqual(normalize_status(types.SimpleNamespace(status=E.COMPLETE)),'COMPLETE')
    def test_conflicting(self):
        with self.assertRaises(Stop):normalize_status({'status':'RUNNING','state':'COMPLETE'})
    def test_nested(self):self.assertEqual(normalize_status({'result':{'status':{'state':'COMPLETE'}}}),'COMPLETE')
    def test_self_reference(self):
        x={};x['status']=x
        with self.assertRaises(Stop):normalize_status(x)
    def test_unknown(self):
        for x in (None,1,True,{},'COMPLETE-ish',"{'status':'COMPLETE'}",'SUCCESS',''):
            with self.subTest(x=x),self.assertRaises(Stop):normalize_status(x)

for raw,expected in [('complete','COMPLETE'),('completed','COMPLETE'),('KernelWorkerStatus.COMPLETE','COMPLETE'),('running','RUNNING'),('queued','QUEUED'),('pending','PENDING'),('error','ERROR'),('failed','ERROR'),('canceled','CANCELLED'),('cancelled','CANCELLED')]:
    def test(self,raw=raw,expected=expected):self.assertEqual(normalize_status({'status':raw}),expected)
    setattr(StatusTests,'test_state_'+raw.replace('.','_'),test)

