class PagingAndRuntimeTests(Base):
    def make_sdk(self, pages):
        from contextlib import nullcontext
        calls=[]
        class Request: pass
        request_mod=types.ModuleType('kagglesdk.competitions.types.competition_api_service');request_mod.ApiListSubmissionsRequest=Request
        enum_mod=types.ModuleType('kagglesdk.competitions.types.competition_enums')
        enum_mod.SubmissionGroup=types.SimpleNamespace(SUBMISSION_GROUP_ALL=0)
        enum_mod.SubmissionSortBy=types.SimpleNamespace(SUBMISSION_SORT_BY_DATE=0)
        def get_page(req):
            calls.append((req.competition_name,req.page_token))
            return pages[min(len(calls)-1,len(pages)-1)]
        service=types.SimpleNamespace(list_submissions=get_page)
        client=types.SimpleNamespace(competitions=types.SimpleNamespace(competition_api_client=service))
        api=types.SimpleNamespace(build_kaggle_client=lambda:nullcontext(client))
        modules={'kagglesdk.competitions.types.competition_api_service':request_mod,'kagglesdk.competitions.types.competition_enums':enum_mod}
        return api,calls,modules
    def test_submission_cursor_preserved(self):
        api,calls,mods=self.make_sdk([types.SimpleNamespace(submissions=[],next_page_token='a'),types.SimpleNamespace(submissions=[{'description':MESSAGE,'ref':2}],next_page_token='')])
        with patch.dict(sys.modules,mods):r=submissions(api)
        self.assertEqual(len(r['submissions']),1);self.assertTrue(r['complete']);self.assertEqual(calls[1][1],'a')
    def test_submission_cursor_loop_blocks(self):
        api,calls,mods=self.make_sdk([types.SimpleNamespace(submissions=[],next_page_token='a')])
        with patch.dict(sys.modules,mods),self.assertRaises(Stop):submissions(api)
    def test_null_submission_blocks_absence(self):
        api,calls,mods=self.make_sdk([types.SimpleNamespace(submissions=[None],next_page_token='')])
        with patch.dict(sys.modules,mods),self.assertRaises(Stop):submissions(api)
    def test_malformed_submissions_blocks(self):
        api,calls,mods=self.make_sdk([types.SimpleNamespace(submissions='bad',next_page_token='')])
        with patch.dict(sys.modules,mods),self.assertRaises(Stop):submissions(api)
    def test_process_timeout_terminates(self):
        from runner import Engine
        import time
        self.out.mkdir()
        e=Engine(self.root,self.out,time.monotonic()+30)
        with patch('runner.rp.system_memory',return_value={'available_bytes':10<<30}),self.assertRaises(Stop):
            e.run([sys.executable,'-c','import time; time.sleep(10)'],'timeout_test',cap=.15)
        self.assertEqual(e.stages[-1]['status'],'stopped')
    def test_return_excludes_csv_and_source(self):
        from runner import package
        import zipfile
