        make_output(self.out/'verified_output_v1',self.info)
        p=self.root/'return.zip';package(self.out,p)
        with zipfile.ZipFile(p) as z:
            self.assertEqual(z.namelist(),['results/run_receipt.json']);self.assertIsNone(z.testzip())

