class DeniedSourceTests(Base):
    def launch_fixture(self):
        k=self.root/DELIVERY_REL/'kernel';k.mkdir(parents=True,exist_ok=True)
        nb={'cells':[{'cell_type':'code','source':'print(1)'}]};save(k/'n.ipynb',nb)
        meta={'id':KERNEL,'is_private':True,'enable_internet':False,'dataset_sources':[self.info['asset_id']],
              'competition_sources':[COMPETITION],'code_file':'n.ipynb'}
        save(k/'kernel-metadata.json',meta)
        self.info['notebook_sha256']=sha(k/'n.ipynb');self.info['metadata_sha256']=sha(k/'kernel-metadata.json')
        save(self.root/DELIVERY_REL/'remote_state.json',{'asset_id':self.info['asset_id'],
             'notebook_sha256':self.info['notebook_sha256'],
             'kernel_push':{'status':'pushed','version':1,'url':'https://www.kaggle.com/code/'+KERNEL}})
