from __future__ import annotations
import hashlib,json,os,subprocess,sys,tempfile,zipfile
from pathlib import Path

def _sha(b): return hashlib.sha256(b).hexdigest()

def _load_payload(archive,tmp):
    with zipfile.ZipFile(archive,'r') as z:
        manifest=json.loads(z.read('PAYLOAD_MANIFEST.json'))
        for name,expected in manifest['files'].items():
            if name.startswith('/') or '..' in Path(name).parts: raise RuntimeError('HANDOFF_UNSAFE_MEMBER')
            data=z.read(name)
            if _sha(data)!=expected: raise RuntimeError('HANDOFF_MEMBER_HASH_MISMATCH '+name)
            out=Path(tmp)/name; out.parent.mkdir(parents=True,exist_ok=True); out.write_bytes(data)
    return manifest

def main():
    archive=Path(sys.argv[0]).resolve()
    with tempfile.TemporaryDirectory(prefix='biohub-v1284-ablation-') as td:
        _load_payload(archive,td)
        if '--self-test' in sys.argv[1:]:
            q=subprocess.run([sys.executable,str(Path(td)/'test_ablation.py')],cwd=td)
            if q.returncode==0: print('BIOHUB_V1284_ABLATION_SELF_TEST_PASSED',flush=True)
            return q.returncode
        sys.path.insert(0,td)
        import campaign
        return campaign.main()
if __name__=='__main__': raise SystemExit(main())

