                if MARKER not in html.unescape(htmlv): raise RuntimeError('PLOTLY_PERSISTENCE')
    if plots!=1 or sentinel not in ''.join(texts): raise RuntimeError('NOTEBOOK_SENTINEL')
    return {'status':'passed','execution_counts':counts,'native_plotly_outputs':plots,'saved_outputs_reopened_and_validated':True,'sha256':hashlib.sha256(Path(path).read_bytes()).hexdigest()}
